", "t": [["patch", "{"path":"D:\\Projects\\local_ai\\strata-lab\\runs\\work\\hermes\\csv_line-1794053153\\csvline.py","old_string":"    fields = []\n    cur = \"\"\n    quoted = False\n    for ch in line:\n        if quoted:\n            if ch == '\"':\n                quoted = False\n            else:\n                cur += ch\n        elif ch == '\"':\n            quoted = True\n        elif ch == sep:\n            fields.append(cur.strip())\n            cur = \"\"\n        else:\n            cur += ch\n    fields.append(cur.strip())\n    return fields","new_string":"    fields = []\n    cur = \"\"\n    quoted = False\n    i = 0\n    n = len(line)\n    while i < n:\n        ch = line[i]\n        if quoted:\n            if ch == '\"':\n                if i + 1 < n and line[i + 1] == '\"':\n                    cur += '\"'\n                    i += 2\n                    continue\n                quoted = False\n            else:\n                cur += ch\n        elif ch == '\"':\n            quoted = True\n        elif ch == sep:\n            fields.append(cur)\n            cur = \"\"\n        else:\n            cur += ch\n        i += 1\n    if quoted:\n        raise ValueError(\"unterminated quote in line\")\n    fields.append(cur)\n    return fields"}"]]}

